'use strict';
const LifeReelUI=(()=>{
 const shown=new Set;let timer=null,token=0,pending=null;
 function stop(){clearTimeout(timer);timer=null;token++}
 function open(s){if(!s.dead)return;stop();const pages=LifeReel.slides(s);let index=0,paused=!!matchMedia('(prefers-reduced-motion: reduce)').matches;const own=token;shown.add(s.seed+':'+s.turn+':'+s.age);modal('<section class="life-reel" aria-label="สไลด์โชว์สรุปชีวิต"></section>');const root=$('#modalBody .life-reel');
 function paint(){if(!root.isConnected)return;clearTimeout(timer);$('#modal').scrollTop=0;const e=pages[index],has=VisualMemory.has(e),final=index===pages.length-1;root.innerHTML=`<div class="reel-top"><span>หนึ่งชีวิตของ ${esc(s.name)}</span><small>${index+1} / ${pages.length}</small></div><div class="reel-progress">${pages.map((_,i)=>`<i class="${i<=index?'seen':''}"></i>`).join('')}</div><figure><canvas width="480" height="180" id="reelScene" role="img" aria-label="ฉากจากบันทึกชีวิต"></canvas><figcaption>${has?'รูปลักษณ์ที่บันทึกไว้ในช่วงนั้น':e.kind==='loss'&&final?'ฉากอำลา':'ภาพสถานที่ประกอบ · ไม่มีภาพรูปลักษณ์เดิมในบันทึกนี้'}</figcaption></figure><span class="eyebrow">อายุ ${e.age} ปี${e.month?' · เดือน '+e.month:''} · ${esc(KINGDOMS[e.realm??s.kingdom][0])}</span><h2 tabindex="-1">${esc(e.title)}</h2>${e.choice?`<p class="reel-choice">คุณเลือก: ${esc(e.choice)}</p>`:''}${e.paragraphs.map(p=>`<p class="reel-story">${esc(StoryPresentation.short(p,220))}</p>`).join('')}<div class="reel-controls"><button class="secondary" id="reelPrev" ${index===0?'disabled':''}>← ก่อนหน้า</button><button class="secondary" id="reelPause" aria-pressed="${paused}">${paused?'▶ เล่นต่อ':'❚❚ พักอ่าน'}</button><button class="primary" id="reelNext">${final?'เก็บชีวิตนี้ไว้ →':'ถัดไป →'}</button></div><div class="reel-footer"><button id="reelDecisions">ดูการตัดสินใจที่บันทึกไว้</button><button id="reelExit">กลับไปการ์ดชีวิต</button></div>`;const canvas=root.querySelector('canvas');if(final&&e.kind==='loss')Illustration.drawScene(canvas,{...s,dead:true,calendar:{...s.calendar,pending:false},sceneOverride:(s.race?Ecology.profile(s).scene:'garden')+'-realm-'+s.kingdom},0);else VisualMemory.draw(canvas,s,e,0);root.querySelector('#reelPrev').onclick=()=>{index--;paint()};root.querySelector('#reelNext').onclick=()=>{if(final){stop();$('#modal').close()}else{index++;paint()}};root.querySelector('#reelPause').onclick=()=>{paused=!paused;paint()};root.querySelector('#reelExit').onclick=()=>{stop();$('#modal').close()};root.querySelector('#reelDecisions').onclick=()=>{stop();decisions(s)};if(!paused&&!final)timer=setTimeout(()=>{if(own===token&&root.isConnected&&$('#modal').open){index++;paint()}},9000)}paint();}
 function decisions(s){const records=LifeReel.records(s).filter(e=>e.choice);modal(`<section class="reel-decisions"><span class="eyebrow">การตัดสินใจที่ยังเก็บไว้ในบันทึก</span><h2>เส้นทางที่คุณเลือก</h2>${records.length?records.map(e=>`<article><small>อายุ ${e.age} ปี · เดือน ${e.month}</small><h3>${esc(e.title)}</h3><p class="reel-choice">${esc(e.choice)}</p><p>${esc(StoryPresentation.short(e.paragraphs[0],180))}</p></article>`).join(''):'<p>ชีวิตนี้ยังไม่มีการตัดสินใจที่บันทึกไว้</p>'}<p class="reel-fine">สมุดประจำวันเก็บจำนวนหน้าจำกัด เหตุการณ์สำคัญที่เก็บไว้จะยังอยู่ในสรุปชีวิต</p><button class="secondary" id="reelReplay">กลับไปดูสไลด์โชว์ →</button></section>`);$('#reelReplay').onclick=()=>open(s)}
 function attempt(){if(!pending)return;const s=pending;if(typeof state==='undefined'||state!==s||!s.dead||screen!=='playing'||tab!=='life'){pending=null;return}if($('#modal').open)return;pending=null;open(s)}
 function bind(root,s){root.querySelectorAll('[data-life-reel]').forEach(b=>b.onclick=()=>open(s));if(root===document&&s===state&&s.dead&&!shown.has(s.seed+':'+s.turn+':'+s.age)){pending=s;setTimeout(attempt,0)}}
 if(typeof document!=='undefined')document.querySelector('#modal').addEventListener('close',()=>{stop();setTimeout(attempt,0)});
 return {open,bind,stop};
})();
